INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 16, 'theory', 'Quiz: CI/CD and deployment');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 16, 0, 'Why is the artifact (image) built once and deployed to all environments?', '["It is cheaper", "Exactly what was tested must reach production", "The registry requires it", "It speeds up the network"]', 1, 'Rebuilding for each environment risks shipping something other than what passed the checks; configuration provides the differences.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 16, 1, 'What is the main risk of a rolling deployment of two servers?', '["You need a copy of the environment", "During the deployment half the capacity is lost, and two versions of the code run at once", "You cannot roll back", "You do not need a load balancer"]', 1, 'The headroom must cover losing one server; changes must be backward compatible.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 16, 2, 'What is the price of the blue/green scheme?', '["Service downtime", "Double resources during the deployment and a database schema compatible with both versions", "Inability to roll back", "No monitoring"]', 1, 'In return, switching and rollback are instant, and capacity does not drop.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 16, 3, 'What does a canary deployment do?', '["Stops the service", "Sends a small share of traffic to the new version, compares metrics, and rolls back if they get worse", "Copies the database", "Turns off monitoring"]', 1, 'Only a small percentage of users are affected, and the share grows in steps.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 16, 4, 'How do you safely remove a column from the database without downtime?', '["Remove it right in the deployment", "Expand, switch to the new one, and when all versions have switched, remove the old", "Stop the service and remove it", "Rename the column"]', 1, 'The schema is shared by the old and new versions of the code: removal is the last step after everyone has switched.');
